            "ExtraText",
            "Extraneous text in resource files",
            "Non-value resource files should only contain elements and attributes. ...",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(
                    ExtraTextDetector.class,
                    Scope.RESOURCE_FILE_SCOPE,
                    Scope.MANIFEST_SCOPE));

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType != ResourceFolderType.VALUES;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Node child = element.getFirstChild();
        while (child != null) {
            if (child.getNodeType() == Node.TEXT_NODE || child.getNodeType() == Node.CDATA_SECTION_NODE) {
                String text = child.getNodeValue();
                if (text != null && !text.trim().isEmpty()) {
                    context.report(ISSUE, child, context.getLocation(child),
                            "Unexpected text found in resource file: " + text);
                }
            }
            child = child.getNextSibling();
        }
    }
}
